// filepath: /home/shrawani/course-project-shellshocked/client.c
void handle_read(char *filename) {
    Message msg;
    init_message(&msg);
    msg.type = MSG_READ;
    strcpy(msg.sender, client.username);
    strcpy(msg.filename, filename);
    msg.ss_id = -1;  // ask NM for primary

    send_message(client.nm_sock, &msg);

    Message response;
    recv_message(client.nm_sock, &response);

    if (response.status != SUCCESS) {
        print_error(response.status);
        return;
    }

    // Connect to SS (primary)
    int ss_sock = connect_to_ss(response.data);
    if (ss_sock < 0) {
        printf("Primary storage server unavailable, requesting replica...\n");

        // Ask NM for replica
        init_message(&msg);
        msg.type = MSG_READ;
        strcpy(msg.sender, client.username);
        strcpy(msg.filename, filename);
        msg.ss_id = -2; // "give me a replica"

        if (send_message(client.nm_sock, &msg) < 0 ||
            recv_message(client.nm_sock, &response) < 0 ||
            response.status != SUCCESS) {
            printf("Error: No replica available\n");
            return;
        }

        ss_sock = connect_to_ss(response.data);
        if (ss_sock < 0) {
            printf("Error: Could not connect to replica storage server\n");
            return;
        }
    }

    // Send read request to SS
    init_message(&msg);
    msg.type = MSG_READ;
    strcpy(msg.filename, filename);
    strcpy(msg.sender, client.username);

    send_message(ss_sock, &msg);
    recv_message(ss_sock, &response);

    if (response.status == SUCCESS) {
        printf("%s\n", response.data);
    } else {
        print_error(response.status);
    }

    close(ss_sock);
}
`````

