### 2.4. Queue replication tasks when a write happens

You already have a robust write path via clients → SS directly (NM just gives SS info). To keep existing logic, we’ll replicate **after a successful write**: the SS will notify NM to queue replication. To avoid changing SS/client semantics heavily, we can piggy-back via an NM-side helper that is called whenever a write session is committed.

Add this helper and worker implementation:

```c
````c
// filepath: /home/shrawani/course-project-shellshocked/nm.c
static void queue_replication_task(const char *filename,
                                   int primary_ss_id,
                                   int sentence_index,
                                   int word_index,
                                   const char *username,
                                   const char *data) {
    pthread_mutex_lock(&nm.repl_mutex);

    int next = (nm.repl_tail + 1) % REPLICATION_QUEUE_CAPACITY;
    if (next == nm.repl_head) {
        // queue full, drop task
        log_formatted(LOG_WARNING, "Replication queue full, dropping task for %s", filename);
        pthread_mutex_unlock(&nm.repl_mutex);
        return;
    }

    ReplicationTask *t = &nm.repl_queue[nm.repl_tail];
    memset(t, 0, sizeof(*t));
    strncpy(t->filename, filename, MAX_FILENAME - 1);
    t->primary_ss_id = primary_ss_id;
    t->sentence_index = sentence_index;
    t->word_index = word_index;
    if (username) strncpy(t->username, username, MAX_USERNAME - 1);
    if (data) strncpy(t->data, data, MAX_BUFFER - 1);
    t->in_use = 1;
    nm.repl_tail = next;

    pthread_cond_signal(&nm.repl_cond);
    pthread_mutex_unlock(&nm.repl_mutex);

    log_formatted(LOG_DEBUG, "Queued replication for %s (primary=%d)", filename, primary_ss_id);
}

static int find_healthy_replica_for_file(FileMetadata *meta, int *out_ss_id) {
    if (!meta || meta->replica_count <= 0) return 0;
    pthread_mutex_lock(&nm.ss_mutex);
    for (int i = 0; i < meta->replica_count; ++i) {
        int rid = meta->replica_ids[i];
        int idx = find_ss_index_by_id(rid);
        if (idx >= 0 && nm.ss_list[idx].active) {
            *out_ss_id = rid;
            pthread_mutex_unlock(&nm.ss_mutex);
            return 1;
        }
    }
    pthread_mutex_unlock(&nm.ss_mutex);
    return 0;
}

static void* replication_worker(void *arg) {
    (void)arg;
    log_formatted(LOG_INFO, "Replication worker started");
    while (1) {
        pthread_mutex_lock(&nm.repl_mutex);
        while (nm.repl_head == nm.repl_tail && nm.repl_running) {
            pthread_cond_wait(&nm.repl_cond, &nm.repl_mutex);
        }
        if (!nm.repl_running && nm.repl_head == nm.repl_tail) {
            pthread_mutex_unlock(&nm.repl_mutex);
            break;
        }
        ReplicationTask task = nm.repl_queue[nm.repl_head];
        nm.repl_queue[nm.repl_head].in_use = 0;
        nm.repl_head = (nm.repl_head + 1) % REPLICATION_QUEUE_CAPACITY;
        pthread_mutex_unlock(&nm.repl_mutex);

        if (!task.in_use) continue;

        // Lookup metadata to find replicas
        FileMetadata *meta = trie_search(nm.file_trie, task.filename);
        if (!meta || meta->replica_count == 0) {
            if (meta) free(meta);
            continue;
        }

        for (int i = 0; i < meta->replica_count; ++i) {
            int replica_ss_id = meta->replica_ids[i];
            if (replica_ss_id == task.primary_ss_id) continue;

            pthread_mutex_lock(&nm.ss_mutex);
            int ss_idx = find_ss_index_by_id(replica_ss_id);
            int active = (ss_idx >= 0 && nm.ss_list[ss_idx].active);
            pthread_mutex_unlock(&nm.ss_mutex);
            if (!active) continue;

            Message m;
            init_message(&m);
            m.type = MSG_REPLICATE_WRITE;
            strncpy(m.filename, task.filename, MAX_FILENAME - 1);
            m.sentence_index = task.sentence_index;
            m.word_index = task.word_index;
            strncpy(m.sender, task.username, MAX_USERNAME - 1);
            strncpy(m.data, task.data, MAX_BUFFER - 1);

            pthread_mutex_lock(&nm.ss_sock_mutexes[ss_idx]);
            int rc = send_message(nm.ss_list[ss_idx].sock, &m);
            pthread_mutex_unlock(&nm.ss_sock_mutexes[ss_idx]);
            if (rc < 0) {
                log_formatted(LOG_WARNING,
                              "Failed to send replicate_write for %s to SS %d",
                              task.filename, replica_ss_id);
            } else {
                log_formatted(LOG_INFO,
                              "Replicated write for %s to SS %d",
