// filepath: /home/shrawani/course-project-shellshocked/client.c
void handle_stream(char *filename) {
    Message msg;
    init_message(&msg);
    msg.type = MSG_READ;
    strcpy(msg.sender, client.username);
    strcpy(msg.filename, filename);
    msg.ss_id = -1;  // primary first

    send_message(client.nm_sock, &msg);

    Message response;
    recv_message(client.nm_sock, &response);

    if (response.status != SUCCESS) {
        print_error(response.status);
        return;
    }
    int ss_sock = connect_to_ss(response.data);
    if (ss_sock < 0) {
        printf("Primary storage server unavailable for streaming, requesting replica...\n");

        init_message(&msg);
        msg.type = MSG_READ;
        strcpy(msg.sender, client.username);
        strcpy(msg.filename, filename);
        msg.ss_id = -2; // ask for replica

        if (send_message(client.nm_sock, &msg) < 0 ||
            recv_message(client.nm_sock, &response) < 0 ||
            response.status != SUCCESS) {
            printf("Failed to get replica for streaming\n");
            return;
        }

        ss_sock = connect_to_ss(response.data);
        if (ss_sock < 0) {
            printf("Failed to connect to replica storage server for streaming\n");
            return;
        }
    }

    Message req;
    init_message(&req);
    req.type = MSG_STREAM;
    strcpy(req.sender, client.username);
    strncpy(req.filename, filename, MAX_FILENAME - 1);
    req.filename[MAX_FILENAME - 1] = '\0';

    if (send_message(ss_sock, &req) < 0) {
        printf("Failed to request stream\n");
        close(ss_sock);
        return;
    }

    /* Receive stream tokens until MSG_STOP */
    Message resp;
    while (1) {
        if (recv_message(ss_sock, &resp) < 0) {
            printf("Stream interrupted\n");
            break;
        }
        if (resp.type == MSG_STOP) {
            break;
        }
        if (resp.type != MSG_DATA) {
            continue;
        }

        printf("%s", resp.data);
        if (resp.status == 1) {
            printf(" ");
        }
        fflush(stdout);
    }

    printf("\n");
    close(ss_sock);
}
`````

`handle_info()` uses NM only and doesn’t talk to SS directly, so no change is needed for failover.

