void* handle_client_connection(void* arg) {
    int client_sock = *((int*)arg);
    free(arg);

    Message msg;
    if (recv_message(client_sock, &msg) < 0 || msg.type != MSG_REG_CLIENT) {
        close(client_sock);
        return NULL;
    }

    // ...existing client registration...

    // Handle client requests
    while (nm.running) {
        if (recv_message(client_sock, &msg) < 0) {
            break;
        }

        log_formatted(LOG_REQUEST, "Request from %s: type=%d, file=%s",
                      msg.sender, msg.type, msg.filename);

        Message response;
        init_message(&response);

        switch (msg.type) {
            // ...all existing cases above remain unchanged...

            case MSG_READ:
            case MSG_WRITE:
            case MSG_STREAM:
            case MSG_UNDO: {
                response.type = MSG_DATA;

                // Access checks (unchanged)
                if (msg.type == MSG_WRITE || msg.type == MSG_UNDO) {
                    if (!check_access(msg.filename, msg.sender, ACCESS_WRITE)) {
                        response.status = ERR_ACCESS_DENIED;
                        send_message(client_sock, &response);
                        break;
                    }
                } else {
                    if (!check_access(msg.filename, msg.sender, ACCESS_READ)) {
                        response.status = ERR_ACCESS_DENIED;
                        send_message(client_sock, &response);
                        break;
                    }
                }

                FileMetadata *meta = trie_search(nm.file_trie, msg.filename);
                if (!meta) {
                    response.status = ERR_FILE_NOT_FOUND;
                    send_message(client_sock, &response);
                    break;
                }

                int target_ss_id = -1;

                if (msg.type == MSG_READ || msg.type == MSG_STREAM) {
                    // For READ/STREAM, allow replica failover if client asks for it
                    if (msg.ss_id == -2) {
                        // client explicitly requested a replica
                        if (!find_healthy_replica_for_file(meta, &target_ss_id)) {
                            response.status = ERR_SS_UNAVAILABLE;
                            free(meta);
                            send_message(client_sock, &response);
                            break;
                        }
                        log_formatted(LOG_INFO, "Failover for %s to replica SS %d",
                                      msg.filename, target_ss_id);
                    } else {
                        // normal: primary
                        target_ss_id = meta->ss_id;
                    }
                } else {
                    // WRITE/UNDO: always use primary to preserve semantics
                    target_ss_id = meta->ss_id;
                }

                pthread_mutex_lock(&nm.ss_mutex);
                int ss_idx = find_ss_index_by_id(target_ss_id);
                if (ss_idx < 0 || !nm.ss_list[ss_idx].active) {
                    pthread_mutex_unlock(&nm.ss_mutex);
                    response.status = ERR_SS_UNAVAILABLE;
                    free(meta);
                    send_message(client_sock, &response);
                    break;
                }

                sprintf(response.data, "%s:%d",
                        nm.ss_list[ss_idx].ip,
                        nm.ss_list[ss_idx].client_port);
                response.status = SUCCESS;
                pthread_mutex_unlock(&nm.ss_mutex);

                // Update access time (unchanged)
                meta->accessed = time(NULL);
                strcpy(meta->last_accessed_by, msg.sender);
                trie_update(nm.file_trie, msg.filename, meta);
                cache_put(nm.cache, msg.filename, meta);
                free(meta);
                log_formatted(LOG_INFO,
                              "Updated access time for %s (accessed by %s)",
                              msg.filename, msg.sender);

                send_message(client_sock, &response);
                break;
            }

            default:
                response.status = ERR_INVALID_OPERATION;
                send_message(client_sock, &response);
                break;
        }
