// filepath: /home/shrawani/course-project-shellshocked/nm.c
static int find_ss_index_by_id(int ss_id) {
    for (int i = 0; i < nm.ss_count; ++i) {
        if (nm.ss_list[i].id == ss_id) return i;
    }
    return -1;
}

static void select_replicas_for_file(FileMetadata *meta) {
    meta->replica_count = 0;
    if (nm.ss_count <= 1) return; // no backups possible

    int primary_idx = find_ss_index_by_id(meta->ss_id);
    if (primary_idx < 0) return;

    int count = 0;
    // Simple round-robin over SS list, skipping primary
    for (int offset = 1; offset <= nm.ss_count && count < NUM_REPLICAS; ++offset) {
        int idx = (primary_idx + offset) % nm.ss_count;
        if (!nm.ss_list[idx].active) continue;
        meta->replica_ids[count++] = nm.ss_list[idx].id;
        nm.ss_list[idx].replica_of[nm.ss_list[idx].replica_count++] = meta->ss_id;
    }
    meta->replica_count = count;

    log_formatted(LOG_INFO,
                  "File %s primary SS %d assigned %d replicas",
                  meta->filename, meta->ss_id, meta->replica_count);
}

static int find_healthy_replica_for_file(FileMetadata *meta, int *out_ss_id) {
    if (!meta || meta->replica_count <= 0) return 0;
    pthread_mutex_lock(&nm.ss_mutex);
    for (int i = 0; i < meta->replica_count; ++i) {
        int rid = meta->replica_ids[i];
        int idx = find_ss_index_by_id(rid);
        if (idx >= 0 && nm.ss_list[idx].active) {
            *out_ss_id = rid;
            pthread_mutex_unlock(&nm.ss_mutex);
            return 1;
        }
    }
    pthread_mutex_unlock(&nm.ss_mutex);
    return 0;
}
