// filepath: /home/shrawani/course-project-shellshocked/nm.c

// Recompute replicas for ALL storage servers after a topology change.
// PRECONDITION: nm.ss_mutex is locked by the caller. - S
void recompute_all_ss_replicas() {
    if (nm.ss_count <= 1) {
        // No replicas possible
        for (int i = 0; i < nm.ss_count; ++i) {
            nm.ss_list[i].replica_count = 0;
        }
        log_formatted(LOG_INFO,
                      "Replica recompute: only %d SS(s), no replicas assigned",
                      nm.ss_count);
        return;
    }

    for (int i = 0; i < nm.ss_count; ++i) {
        int assigned = 0;

        // Ring: next NUM_REPLICAS active SSs after i
        for (int step = 1; step < nm.ss_count && assigned < NUM_REPLICAS; ++step) {
            int idx = (i + step) % nm.ss_count;
            if (!nm.ss_list[idx].active || nm.ss_list[idx].recovering) {
                continue;
            }
            nm.ss_list[i].replica_of[assigned] = nm.ss_list[idx].id;
            assigned++;
        }

        nm.ss_list[i].replica_count = assigned;
        log_formatted(LOG_INFO,
                      "SS %d assigned %d replicas",
                      nm.ss_list[i].id, assigned);
    }
}
```

This implements:

- 1 SS: no replicas.
- 2 SSs: each gets the other as replica.
- 3+ SSs: ring pattern, balanced.

