void update_all_file_replicas() {
    // Collect all files from trie
    FileMetadata *files[MAX_FILES];
    int file_count = trie_get_all_files(nm.file_trie, files, MAX_FILES);

    pthread_mutex_lock(&nm.ss_mutex);

    for (int i = 0; i < file_count; ++i) {
        FileMetadata *meta = files[i];
        int primary_ss_id = meta->ss_id;

        int primary_idx = -1;
        for (int s = 0; s < nm.ss_count; ++s) {
