        meta->replica_count = nm.ss_list[primary_idx].replica_count;
        for (int r = 0; r < meta->replica_count; ++r) {
            meta->replica_ids[r] = nm.ss_list[primary_idx].replica_of[r];
        }

        // Persist updated metadata
        trie_update(nm.file_trie, meta->filename, meta);
        cache_put(nm.cache, meta->filename, meta);
