                    log_formatted(LOG_WARNING,
                                  "Replica SS %d not available for create of %s",
                                  replica_ss_id, msg->filename);
                    continue;
                }

                Message rep_msg;
                init_message(&rep_msg);
                rep_msg.type = MSG_CREATE;
                strcpy(rep_msg.filename, msg->filename);

                pthread_mutex_lock(&nm.ss_sock_mutexes[rep_idx]);
                int rc = send_message(nm.ss_list[rep_idx].sock, &rep_msg);
                Message rep_resp;
                if (rc == 0 &&
                    recv_message(nm.ss_list[rep_idx].sock, &rep_resp) == 0 &&
                    rep_resp.status == SUCCESS) {
                    log_formatted(LOG_INFO,
                                  "Replicated create of %s on replica SS %d",
                                  msg->filename, replica_ss_id);
                } else {
                    log_formatted(LOG_WARNING,
                                  "Failed to replicate create of %s on replica SS %d",
                                  msg->filename, replica_ss_id);
                }
                pthread_mutex_unlock(&nm.ss_sock_mutexes[rep_idx]);
            }

            free(meta_with_replicas);
        }

        response.status = SUCCESS;
        log_formatted(LOG_INFO, "Created file %s by %s on SS %d",
                      msg->filename, msg->sender, ss_id);
    } else {
        response.status = ss_response.status;
    }
```

