static int read_full_file(const char *filename, char *buffer, size_t buf_size) {
    char filepath[MAX_PATH];
    snprintf(filepath, sizeof(filepath), "%s/%s", ss.storage_path, filename);

    FILE *file = fopen(filepath, "r");
